# region: fold
def fold(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: render
def render(xs, limit=9):
    return [v if v <= limit else limit for v in xs[1:]]

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: digest
def digest(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(emit(render(fold(raw))))

